import {firstObjectivePassage} from './objective-routing.js?v=5.11.0';
import {nodesFor,nodeState,availablePoints} from './skill-grid-model.js?v=5.16.0';
import {RARE_MAKO,isMakoAttuned} from './wayglass-model.js?v=5.11.0';
import {SCHOOLS,learnedSchool} from './constellation-model.js';
export const SUPPLY_TARGETS={tonic:3,ether:2,revive:1};
export function guidanceState(s){return s.guidance??={version:1,shops:[],seenScenes:[],quiet:false};}
export function supplyNeeds(s){return Object.entries(SUPPLY_TARGETS).filter(([id,count])=>(s.items?.[id]||0)<count).map(([id,count])=>({id,missing:count-(s.items?.[id]||0)}));}
export function clearSight(scene,from,to){const length=Math.hypot(to[0]+.5-from[0],to[1]+.5-from[1]),steps=Math.ceil(length*4);for(let i=1;i<steps;i++){const t=i/steps;if(scene.floor[Math.floor(from[1]+(to[1]+.5-from[1])*t)]?.[Math.floor(from[0]+(to[0]+.5-from[0])*t)]==='#')return false;}return true;}
export function observeServices(w){const s=w.state,p=guidanceState(s);if(!p.seenScenes.includes(s.scene))p.seenScenes.push(s.scene);for(const o of w.objects().filter(o=>o.type==='shop'&&o.xy)){if(Math.hypot(s.x-o.xy[0]-.5,s.y-o.xy[1]-.5)>7||!clearSight(w.scene,[s.x,s.y],o.xy))continue;const key=s.scene+':'+o.xy.join(',');if(!p.shops.some(x=>x.key===key))p.shops.push({key,scene:s.scene,xy:o.xy.slice(),label:o.label||'Supply merchant',place:w.scene.title||w.scene.name||w.scene.key});}}
/** Recommendations never spend points, choose forks, buy supplies or equip items. */
export function guidanceActions(s){const out=[];if(s.story&&!s.story.firstCore)return out;for(const hero of s.recruited||[]){const h=s.heroes[hero],nodes=nodesFor(hero),available=nodes.filter(n=>nodeState(s,hero,n)==='available');for(const r of RARE_MAKO)if(isMakoAttuned(s,hero,r.id)&&!(h.loadout||[]).some(x=>x.makoId===r.id))out.push({id:'rare:'+hero+':'+r.id,kind:'craft',hero,mako:r.id,title:h.name+' · fit '+r.name,detail:r.effect});if(available.length){const choice=available.find(n=>n.stat==='mako')||available[0];out.push({id:'growth:'+hero,kind:choice.doctrine?'school':'growth',hero,school:choice.school,node:choice.id,title:h.name+' · '+availablePoints(s,hero)+' growth available',detail:available.length+' affordable choices. Inspect the highlighted node before spending.'});}const school=SCHOOLS.find(x=>learnedSchool(s,hero,x.id).root&&!(h.doctrineSlots||[]).includes(x.id));if(school)out.push({id:'school:'+hero,kind:'school',hero,school:school.id,title:h.name+' · '+school.name+' learned',detail:'Review school slots and capacity before equipping it.'});}const needs=supplyNeeds(s),p=s.guidance;if(needs.length&&p?.shops?.length){const shop=[...p.shops].sort((a,b)=>(b.scene===s.scene)-(a.scene===s.scene))[0];out.push({id:'supplies:'+shop.key,kind:'vendor',shop,title:'Restock at '+shop.label,detail:needs.map(x=>x.id+' ×'+x.missing).join(' · ')+' to reach a small travel reserve. '+(shop.scene===s.scene?'This merchant is in this room.':'Last seen: '+shop.place+'.')});}return out;}
/** Only remembered rooms are routed. Doors retain story and access gates. */
export function vendorWaypoint(w,shop){if(w.state.scene===shop.scene)return {kind:'shop',object:w.objects().find(o=>o.type==='shop'&&o.xy.join(',')===shop.xy.join(','))};const passage=firstObjectivePassage(w,shop.scene,{knownScenes:new Set(w.state.guidance?.seenScenes||[])});if(!passage)return null;const original=[...(w.scene.doors||[]),...(w.scene.objects||[])].find(o=>o.xy?.join(',')===passage.xy.join(',')&&o.to===passage.to&&o.to_region===passage.to_region&&o.to_room===passage.to_room&&o.type!=='transport');return {kind:passage.type==='transport'?'transport':'door',object:passage.type==='transport'?passage:original||passage};}
